/* Generated by gen_pipe.py.  Pure vfmacc chain calibration, no spill control.
   Each kernel streams one f64 vector per VLMAX block and keeps NACC independent
   accumulators live across eight fused multiply-adds.  fma_elems counts
   n*k*NACC*CHAIN fused operations so fma_elems/cycles is the sustained
   FMA-element throughput; cycles/(n*k) is the per-element time.  Auxiliary
   calibration only, not part of the audited libmvec matrix.
   SPDX-License-Identifier: LGPL-2.1-or-later */
#include <stddef.h>
#include <stdint.h>
#include <riscv_vector.h>
/* Same bare-metal stdio shim as the measured harness (printf -> printf_). */
#include "../../autovec/av_runtime.h"

#define CAT_(a,b) a##b
#define CAT(a,b) CAT_(a,b)
#define VOP(name,t) CAT(CAT(__riscv_,name),t)

#define ROUNDS 10
#ifndef CHAIN
#define CHAIN 8
#endif

static inline uint64_t cycle(void)
{
    uint64_t c;
    __asm__ volatile("rdcycle %0" : "=r"(c) :: "memory");
    return c;
}

static volatile uint64_t sink;

/* ---- m1 nacc=1 ---- */
#define VLMAX VOP(vsetvlmax_e64, m1)()
#define VLE VOP(vle64_v_f64, m1)
#define VSE VOP(vse64_v_f64, m1)
#define VFMV VOP(vfmv_v_f_f64, m1)
#define VFMACC VOP(vfmacc_vf_f64, m1)
#define VFADD VOP(vfadd_vv_f64, m1)
#define VT vfloat64m1_t
void pipe_m1_a1(size_t n, const double *x, const double *z, double *y)
{
    (void)z;
    size_t vl = VLMAX;
    size_t i = 0;
    for (; i + vl <= n; i += vl) {
        VT v = VLE(x + i, vl);
        const double c0 = 1.0000001 + 0.0e-7;
        VT a0 = VFMV(1.0, vl);
        for (unsigned r = 0; r < CHAIN; ++r) {
            a0 = VFMACC(v, c0, a0, vl);
        }
        VT s = a0;
        VSE(y + i, s, vl);
    }
    sink = (uint64_t)i;
}
#undef VLMAX
#undef VLE
#undef VSE
#undef VFMV
#undef VFMACC
#undef VFADD
#undef VT

